  "E-02": {
    "code": "E-02",
    "name": {
      "es": "Pago rechazado",
      "en": "Payment declined"
    },
    "purpose": {
      "es": "Pago rechazado: explicar, reintentar, cambiar método o pedir ayuda a recepción.",
      "en": "A refusal is the highest-risk moment in the funnel: say what happened, confirm nothing was charged, keep the class reserved, and offer a way through."
    },
    "layout": [
      "ErrorBanner",
      "HoldCard · 9:00 countdown",
      "AlternateMethods",
      "ReleaseSpotLink (destructive)"
    ],
    "data": [
      "payments",
      "orders",
      "bookings",
      "payment_methods",
      "gateway_responses",
      "holds"
    ],
    "roles": [
      "customer",
      "front_desk",
      "finance"
    ],
    "logic": [
      "Never blame the card; state the gateway reason verbatim where one exists and keep it plain.",
      "The spot is held 10 minutes from the first attempt; the countdown is visible and honest.",
      "Three declines on one order switch the primary suggestion to PSE or cash.",
      "No charge is ever captured on a decline; the order stays pending and the audit trail records every attempt.",
      "Cash creates a pending order the front desk settles — the same path as C-05."
    ],
    "integrations": [
      "Wompi"
    ],
    "states": [
      "Declined (this screen)",
      "Retrying: button spinner, methods locked",
      "Hold expired: spot released, rebook offered",
      "Recovered: confirmation sheet"
    ],
    "toggles": [
      {
        "label": "10-minute spot hold",
        "on": true
      },
      {
        "label": "Show gateway reason",
        "on": true
      },
      {
        "label": "Cash fallback",
        "on": true
      }
    ],
    "story": "As a student whose card was declined I switch to Nequi within the hold window and keep my 6pm class.",
    "api": [
      "POST /payments/intent",
      "GET /orders/:id",
      "POST /orders/:id/method",
      "DELETE /holds/:id"
    ],
    "layerTree": "PaymentDeclined\n├ ErrorBanner\n│ ├ Title + body\n│ └ GatewayReason\n├ HoldCard · 9:00 countdown\n├ AlternateMethods\n│ ├ Other saved methods\n│ └ Cash at front desk\n└ ReleaseSpotLink (destructive)",
    "canvasRef": "reference/canvas/Hoy Wellness System.dc.html#E-02"
  },
